        if (host.contains(" ")) {
            throw new IllegalArgumentException("Host contains invalid characters.");
        }

        // Construct the full URL with the sanitized host
        String sanitizedUrl = "http://" + host + parsedUrl.getPath() + parsedUrl.getQuery();

        // Fetch and return the content from the URL
        return fetchContent(sanitizedUrl);
    }

