    public static String fetchContent(String urlString) {
        try {
            // Parse de URL
            URL url = new URL(urlString);

            // Haal de host op
            String host = url.getHost();

            // Valideer en schoon de host
            String cleanedHost = validateAndCleanHost(host);

            // Maak een nieuwe URL met de schoonde host
            URL validatedUrl = new URL("http://" + cleanedHost + url.getPath() + url.getQuery());

            // Haal de inhoud van de URL
            String content = getContent(validatedUrl);

            return content;
        } catch (MalformedURLException e) {
            System.err.println("Invalid URL: " + urlString);
            return null;
        }
    }

    private static String validateAndCleanHost(String host) {
        // Regex voor ongeldige tekens in de host
        Pattern pattern = Pattern.compile("[^a-zA-Z0-9.-]");
        Matcher matcher = pattern.matcher(host);

        // Verwijder ongeldige tekens
        if (matcher.find()) {
            host = matcher.replaceAll("");
        }

        return host;
    }

