     */
    public static String getContentFromURL(String urlString) {
        try {
            // Create a URL object from the provided URL string
            URL url = new URL(urlString);

            // Open a connection to the URL
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();

            // Set the request method to GET
            connection.setRequestMethod("GET");

            // Check if the response code is OK (200)
            if (connection.getResponseCode() == HttpURLConnection.HTTP_OK) {
                // Read the input stream from the connection
                BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()));

                // StringBuilder to store the content
                StringBuilder contentBuilder = new StringBuilder();

                // Read line by line and append to the content builder
                String line;
                while ((line = reader.readLine())!= null) {
                    contentBuilder.append(line).append("\n");
                }

                // Close the reader
                reader.close();

                // Return the content as a string
                return contentBuilder.toString().trim(); // Trim to remove any trailing newline characters
            } else {
                // If the response code is not OK, throw an exception
                throw new IOException("Failed to retrieve content. Response code: " + connection.getResponseCode());
            }
        } catch (IOException e) {
            // Handle any I/O exceptions that may occur
            e.printStackTrace();
            return null;
        }
    }
}
