public static String getContentFromURL(String url) {
        try {
            // Validar el host
            String sanitizedHost = validateHost(url);

            // Construir la URL completa
            URL fullUrl = new URL("http://" + sanitizedHost + url.substring(url.indexOf("/")));

            // Obtener el contenido de la URL
            return getContent(fullUrl);
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }

    private static String validateHost(String url) {
        // Verificar si el host contiene espacios
        if (url.contains(" ")) {
            throw new IllegalArgumentException("El host no puede contener espacios.");
        }

        // Extraer el host desde la URL
        int start = url.indexOf("//") + 2;
        int end = url.indexOf("/", start);
        if (end == -1) {
            end = url.length();
        }
        String host = url.substring(start, end);

        return host;
    }

    private static String getContent(URL url) throws Exception {
        // Implementación de la lógica para obtener el contenido de la URL
        // Por ejemplo, usando HttpURLConnection o HttpClient
        // return new String(url.openStream().readAllBytes());
        return "Contenido obtenido de la URL: " + url.toString();
    }
}
