public static String fetchContentFromURL(String urlString) throws Exception {
        // Erstelle eine URL-Instanz aus dem übergebenen String
        URL url = new URL(urlString);

        // Extrahiere den Host aus der URL
        String host = url.getHost();

        // Validiere den Host: Entferne ungültige Zeichen wie Leerzeichen
        host = host.replaceAll("\\s", "");

