public static String fetchContentFromURL(String urlString) {
        try {
            URL url = new URL(urlString);
            // Assuming the URL is valid, proceed to fetch content
            // Here you would typically use a library like HttpURLConnection or Apache HttpClient
            // For simplicity, let's assume we're using HttpURLConnection
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");
            connection.connect();

            int responseCode = connection.getResponseCode();
            if (responseCode == HttpURLConnection.HTTP_OK) {
                // Read the input stream to get the content
                try (BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
                    StringBuilder contentBuilder = new StringBuilder();
                    String line;
                    while ((line = reader.readLine())!= null) {
                        contentBuilder.append(line).append("\n");
                    }
                    return contentBuilder.toString();
                }
            } else {
                System.out.println("Failed to connect. Response code: " + responseCode);
                return null;
            }
        } catch (Exception e) {
            System.err.println("Error fetching content from URL: " + e.getMessage());
            return null;
        }
    }

