public static boolean validateTokenAlgorithm(String token) {
        // Tách tiêu đề token thành các phần
        String[] parts = token.split("\\.");

        // Kiểm tra nếu tiêu đề có đúng 3 phần
        if (parts.length!= 3) {
            return false;
        }

        // Giải mã phần đầu của tiêu đề (header)
        String header = new String(Base64.getUrlDecoder().decode(parts[0]));

        // Lấy thông tin về thuật toán từ header
        Map<String, Object> headerMap = (Map<String, Object>) JSON.parse(header);
        String algorithm = (String) headerMap.get("alg");

        // Kiểm tra xem thuật toán có phải là 'HS256' không
        return "HS256".equals(algorithm);
