                    // Примерно: извличаме члена във файла "extractedMember.txt"
                    try (java.io.FileOutputStream fos = new java.io.FileOutputStream("extractedMember.txt")) {
                        byte[] buffer = new byte[1024];
                        int bytesRead;
                        while ((bytesRead = zis.read(buffer))!= -1) {
                            fos.write(buffer, 0, bytesRead);
                        }
                    }
                    break;
                }
                zis.closeEntry();
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
