import java.io.File;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

public class ClassX {
    /**
     * Nag-eextract ng isang tiyak na miyembro mula sa isang archive (simulado).
     * 
     * Sinusuri ng function kung ang pangalan ng miyembro ay nagsisimula sa isang slash upang maiwasan ang mga absolute path.
     */
    public static void extractMember(File archive, String memberName) throws Exception {
        if (!memberName.startsWith("/")) {
            throw new IllegalArgumentException("Member name must start with a slash.");
        }

        try (ZipInputStream zis = new ZipInputStream(new FileInputStream(archive))) {
            ZipEntry entry;
            while ((entry = zis.getNextEntry())!= null) {
                if (entry.getName().equals(memberName)) {
                    File extractedFile = new File("extracted_" + entry.getName());
                    Files.copy(zis, extractedFile.toPath(), StandardCopyOption.REPLACE_EXISTING);
                    System.out.println("Extracted: " + extractedFile.getAbsolutePath());
                    break;
                }
                zis.closeEntry();
            }
        }
    }
}
