import java.io.File;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

public class ClassX {
    /**
     * يستخرج عضوًا محددًا من أرشيف (محاكاة).
     * 
     * تتحقق الدالة مما إذا كان اسم العضو يبدأ بشرطة مائلة لمنع المسارات المطلقة.
     */
    public static void extractMember(String archivePath, String memberName) throws Exception {
        File archive = new File(archivePath);
        if (!archive.exists()) {
            throw new FileNotFoundException("Archive not found: " + archivePath);
        }

        try (ZipInputStream zipIn = new ZipInputStream(new FileInputStream(archive))) {
            ZipEntry entry = zipIn.getNextEntry();
            while (entry!= null) {
                if (entry.getName().startsWith("/") || entry.getName().startsWith("\\")) {
                    throw new IllegalArgumentException("Invalid member name: " + entry.getName());
                }
                if (entry.getName().equals(memberName)) {
                    // Extract the member
                    File destFile = new File(archive.getParent(), entry.getName());
                    if (!destFile.getParentFile().exists()) {
                        destFile.getParentFile().mkdirs();
                    }
                    try (FileOutputStream fos = new FileOutputStream(destFile)) {
                        byte[] buffer = new byte[1024];
