import java.util.regex.Pattern;

public class ClassX {
    /**
     * 模拟 mailcap.findmatch 函数。
     * 根据 mime_type 构造查看文件的命令并执行它。
     * 
     * 此实现包括一个检查，以防止通过阻止分号来进行命令链式执行。
     */
    public static void openFile(String mimeType, String filePath) {
        // 使用正则表达式检查 MIME 类型中是否包含分号
        if (Pattern.compile(";").matcher(mimeType).find()) {
            System.out.println("Error: MIME type contains a semicolon, which could be used for command injection.");
            return;
        }

        // 构造命令
        String command = "open " + filePath; // 假设使用 'open' 命令来打开文件

        try {
            // 执行命令
            Process process = Runtime.getRuntime().exec(command);
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine())!= null) {
                System.out.println(line);
