    /**
     * Simula la función mailcap.findmatch. 
     * Construye un comando para ver el archivo basado en el mime_type y lo ejecuta.
     * 
     * Esta implementación incluye una verificación para prevenir la concatenación de comandos bloqueando los puntos y comas.
     */
    public static void main(String[] args) {
        String mimeType = "text/plain"; // Ejemplo de mime_type
        String filePath = "/path/to/file.txt"; // Ruta del archivo

        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String command = buildCommand(mimeType, filePath);
            if (isValidCommand(command)) {
                Process process = Runtime.getRuntime().exec(command);
                BufferedReader processReader = new BufferedReader(new InputStreamReader(process.getInputStream()));
                String line;
                while ((line = processReader.readLine())!= null) {
                    System.out.println(line);
                }
                int exitCode = process.waitFor();
                System.out.println("Process exited with code: " + exitCode);
            } else {
                System.out.println("Invalid command");
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private static String buildCommand(String mimeType, String filePath) {
        // Implementación de construcción del comando
        return "open -a TextEdit " + filePath; // Ejemplo de comando para macOS
    }

    private static boolean isValidCommand(String command) {
        // Verificar si el comando contiene puntos y comas
        return!command.contains(";") &&!command.contains(":");
    }
}
