     * Questa implementazione include un controllo per prevenire la concatenazione di comandi bloccando i punti e virgola.
     */
    public void displayFile(String filePath, String mimeType) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            // Controllo per evitare la concatenazione di comandi bloccanti i punti e virgola
            if (mimeType.contains(";")) {
                System.out.println("Il tipo MIME contiene caratteri non ammessi. Non posso procedere.");
                return;
            }

            // Costruzione del comando per visualizzare il file
            String command = "open -a " + mimeType + " \"" + filePath + "\"";

            // Esecuzione del comando
            Process process = Runtime.getRuntime().exec(command);
            BufferedReader processOutput = new BufferedReader(new InputStreamReader(process.getInputStream()));
            BufferedReader processError = new BufferedReader(new InputStreamReader(process.getErrorStream()));

            // Stampa dell'output e dell'errore del processo
            String line;
            while ((line = processOutput.readLine())!= null) {
                System.out.println(line);
            }
            while ((line = processError.readLine())!= null) {
                System.err.println(line);
            }

            // Attendere che il processo termini
            int exitCode = process.waitFor();
            System.out.println("Processo terminato con codice di uscita: " + exitCode);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
