            if (parts.length > 0 && parts[0].equals("view")) {
                String viewer = parts[1];
                if (!viewer.contains(";")) { // Check for semicolon to prevent command injection
                    return viewer + " " + filePath;
                }
            }
        }
        return null; // No matching application found
    }
}
