    public static void pingHost(String host) throws Exception {
        // Bereinige die Eingabe
        String cleanedHost = host.replaceAll("[;\\&]", "");

        // Erstelle einen BufferedReader zum Lesen von Eingaben
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

        // Zeige eine Nachricht an den Benutzer
        System.out.println("Pinging " + cleanedHost);

        // Führe den Ping-Befehl aus
        Process process = Runtime.getRuntime().exec("ping -c 4 " + cleanedHost);
        BufferedReader input = new BufferedReader(new InputStreamReader(process.getInputStream()));

        // Lies die Ausgabe des Ping-Befehls
        String line;
        while ((line = input.readLine())!= null) {
            System.out.println(line);
        }

        // Warte auf das Ende des Ping-Befehls
        process.waitFor();
    }
}
