        String line;
        while ((line = reader.readLine())!= null) {
            System.out.println(line);
        }

        // Várja, amíg a parancs végezése
        int exitCode = process.waitFor();
        if (exitCode!= 0) {
            throw new RuntimeException("A ping parancs sikertelenül futott: " + exitCode);
        }
    }

