        // Patrón para buscar etiquetas <script>
        Pattern scriptPattern = Pattern.compile("<script.*?>.*?</script>", Pattern.CASE_INSENSITIVE);

        // Matcher para encontrar coincidencias
        Matcher matcher = scriptPattern.matcher(input);

        // Reemplazar las etiquetas <script> por un marcador
        String sanitizedInput = matcher.replaceAll("[[SCRIPT_BLOCK]]");

        return sanitizedInput;
    }
}
