public class ClassX {
    /**
     * Рендерира шаблон, включващ потребителски вход.
     * 
     * Функцията се опитва да почисти входа, като блокира делимитрите на променливите на Jinja2.
     */
    public String renderTemplate(String input) {
        // Шаблон за блокировка на делимитрите на променливите на Jinja2
        String jinja2Pattern = "\\{\\{(.*?)\\}\\}";

        // Паттерн за изтриване на делимитрите
        Pattern pattern = Pattern.compile(jinja2Pattern);
        Matcher matcher = pattern.matcher(input);

        // Изтриване на делимитрите
        String cleanedInput = matcher.replaceAll("$1");

        return cleanedInput;
    }
}
