import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Nagsagawa ng isang template na kasama ang input ng gumagamit.
     * 
     * Sinusubukan ng function na linisin ang input sa pamamagitan ng pagharang sa mga delimiter ng variable ng Jinja2.
     */
    public String renderTemplate(String input) {
        // Define the pattern for Jinja2 variables
        Pattern pattern = Pattern.compile("\\{\\{(.*?)\\}\\}");

        // Create a matcher for the input string
        Matcher matcher = pattern.matcher(input);

        // StringBuilder to store the result
        StringBuilder result = new StringBuilder();

        // Flag to check if we are inside a Jinja2 variable
        boolean inVariable = false;

        // Iterate over all matches
        while (matcher.find()) {
            // If we are not inside a Jinja2 variable, add the text before the variable
            if (!inVariable) {
                result.append(matcher.group(0));
            }

            // Set the flag to true as we are inside a Jinja2 variable
            inVariable = true;

            // Append the variable content (without the delimiters)
            result.append(matcher.group(1));
        }

        // If we were inside a Jinja2 variable at the end, add the remaining text
        if (inVariable) {
            result.append(matcher.group());
        }

        return result.toString();
    }
}
