     * Η συνάρτηση προσπαθεί να καθαρίσει την είσοδο αποκλείοντας τους διαχωριστές μεταβλητών Jinja2.
     */
    public String sanitizeInput(String input) {
        // Regular expression to match Jinja2 variables
        Pattern pattern = Pattern.compile("\\{\\{(.*?)\\}\\}");
        Matcher matcher = pattern.matcher(input);

        // Replace Jinja2 variables with empty strings
        while (matcher.find()) {
            input = input.replace(matcher.group(), "");
        }

        return input;
    }
}
