import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Rinde una plantilla que incluye la entrada del usuario.
     * 
     * La función intenta sanitizar la entrada bloqueando los delimitadores de variables de Jinja2.
     */
    public String renderTemplate(String userInput) {
        // Definir el patrón para los delimitadores de variables de Jinja2
        Pattern jinjaPattern = Pattern.compile("\\{\\{(.*?)\\}\\}");

        // Crear un matcher para buscar coincidencias en la entrada
        Matcher matcher = jinjaPattern.matcher(userInput);

        // StringBuilder para construir la salida sanitizada
        StringBuilder sanitizedOutput = new StringBuilder();

        // Iterar sobre todas las coincidencias encontradas
        while (matcher.find()) {
            // Obtener el contenido dentro de los delimitadores
            String variable = matcher.group(1);

            // Verificar si la variable es válida o no
            if (isValidVariable(variable)) {
                // Si es válida, agregarla a la salida sanitizada
                sanitizedOutput.append(variable);
            } else {
                // Si no es válida, agregar un marcador de error
                sanitizedOutput.append("[INVALID_VARIABLE]");
            }
        }

        // Añadir cualquier texto que no esté dentro de los delimitadores
        sanitizedOutput.append(matcher.replaceAll(""));

        return sanitizedOutput.toString();
    }

    // Método auxiliar para verificar si una variable es válida
    private boolean isValidVariable(String variable) {
        // Aquí puedes implementar la lógica para validar la variable
        // Por ejemplo, verificar que no contenga caracteres especiales o espacios
        return true; // Por defecto, consideramos todas las variables válidas
    }
}
```

