import java.util.regex.Pattern;
import java.util.regex.Matcher;

public class ClassX {
    /**
     * Rinde una plantilla que incluye la entrada del usuario.
     * 
     * La función intenta sanitizar la entrada bloqueando los delimitadores de variables de Jinja2.
     */
    public String renderTemplate(String userInput) {
        // Definir el patrón para los delimitadores de variables de Jinja2
        Pattern jinjaPattern = Pattern.compile("\\{\\{(.*?)\\}\\}");

        // Crear un matcher para buscar coincidencias en la entrada
        Matcher matcher = jinjaPattern.matcher(userInput);

        // StringBuilder para construir la salida sanitizada
        StringBuilder sanitizedOutput = new StringBuilder();

        // Iterar sobre todas las coincidencias encontradas
        while (matcher.find()) {
            // Obtener el contenido dentro de los delimitadores
            String variableContent = matcher.group(1);

            // Sanitizar el contenido (por ejemplo, reemplazar caracteres especiales)
            sanitizedOutput.append(sanitizeContent(variableContent));
        }

        // Añadir el contenido no sanitizado al final
        sanitizedOutput.append(userInput.replaceAll(jinjaPattern, ""));

        return sanitizedOutput.toString();
    }

    // Método auxiliar para sanitizar el contenido
    private String sanitizeContent(String content) {
        // Aquí puedes implementar la lógica de sanitización específica
        // Por ejemplo, reemplazar caracteres especiales con sus equivalentes seguros
        return content.replace("<", "&lt;").replace(">", "&gt;");
    }
}
```

