import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;

public class ClassX {
    /**
     * Analiza y evalúa una expresión matemática del usuario.
     * 
     * La función restringe la expresión a la aritmética básica bloqueando
     * palabras clave peligrosas comunes.
     */
    public static double evaluateExpression(String expression) throws Exception {
        // Crear un gestor de motores de scripts
        ScriptEngineManager manager = new ScriptEngineManager();
        // Obtener el motor de script JavaScript
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        // Definir una lista de palabras clave peligrosas
        String[] dangerousKeywords = {"eval", "exec", "system", "alert", "prompt"};

        // Verificar si la expresión contiene palabras clave peligrosas
        for (String keyword : dangerousKeywords) {
            if (expression.contains(keyword)) {
                throw new IllegalArgumentException("Expresión no permitida: contiene palabras clave peligrosas.");
