public static void evaluateExpression(String expression) {
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        // Bloquer les mots-clés dangereux
        String blockedKeywords = "eval,setTimeout,setInterval,with,delete,try,catch,finally,throw,arguments,console,XMLHttpRequest";
        for (String keyword : blockedKeywords.split(",")) {
            expression = expression.replaceAll("\\b" + keyword + "\\b", "");
        }

        try {
            Object result = engine.eval(expression);
            System.out.println("Résultat : " + result);
        } catch (Exception e) {
            System.err.println("Erreur d'évaluation : " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        // Exemple d'utilisation
        String userInput = "2 + 3 * 4";
        evaluateExpression(userInput);
    }
}
