public static double evaluateExpression(String expression) {
        // Erstellen eines ScriptEngineManagers
        ScriptEngineManager manager = new ScriptEngineManager();

        // Abrufen des ScriptEngine für JavaScript
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        // Blockieren häufige gefährliche Schlüsselwörter
        String sanitizedExpression = expression.replaceAll("(?i)(eval|exec|system|command|os|shell)", "BLOCKED");

        try {
            // Evaluieren des bereinigten Ausdrucks
            return (double) engine.eval(sanitizedExpression);
        } catch (Exception e) {
            // Behandlung von Fehlern
            System.err.println("Fehler beim Evaluieren des Ausdrucks: " + e.getMessage());
            return Double.NaN; // Rückgabe NaN bei Fehlern
        }
    }
}
