            pw.println("Hata ayıklama bilgileri:");
            pw.println(getStackTraceDetail());
        }

        pw.close();
        return sw.toString();
    }

    private static boolean isProductionEnvironment() {
        // Bu metot, üretim ortamını belirlemek için kullanılır
        // Örneğin, environment değişkenine göre kontrol edilebilir
        return System.getenv("ENVIRONMENT").equals("production");
    }

    private static String getStackTraceDetail() {
        // Bu metot, hata ayıklama bilgilerini içeren bir metni döndürür
        // Örneğin, StackTraceElement'leri kullanarak bilgi alabilirsiniz
        StackTraceElement[] stackTraceElements = Thread.currentThread().getStackTrace();
        StringBuilder sb = new StringBuilder();
        for (StackTraceElement element : stackTraceElements) {
            sb.append(element.toString()).append("\n");
        }
        return sb.toString();
    }
}
