public static String getDebugInfo() {
        // 检查是否为生产环境
        if (isProductionEnvironment()) {
            return "Debug information suppressed due to production environment.";
        }

        // 创建 StringWriter 来捕获异常信息
        StringWriter sw = new StringWriter();
        PrintWriter pw = new PrintWriter(sw);

        try {
            // 获取当前线程的堆栈跟踪信息
            StackTraceElement[] stackTraceElements = Thread.currentThread().getStackTrace();

            // 遍历堆栈跟踪信息并打印到 StringWriter 中
            for (StackTraceElement element : stackTraceElements) {
                pw.println(element.toString());
            }
        } catch (Exception e) {
            // 如果发生异常，打印错误信息
            pw.println("Error occurred while retrieving debug information: " + e.getMessage());
        } finally {
            // 关闭 PrintWriter
            pw.close();
        }

        // 返回捕获的调试信息
        return sw.toString();
    }

    /**
     * 检查当前环境是否为生产环境。
     * 
     * 这是一个简单的示例实现，实际应用中可能需要更复杂的逻辑来判断生产环境。
     */
    private static boolean isProductionEnvironment() {
        // 在实际应用中，可以根据配置文件、系统属性或其他方式判断生产环境
        return false; // 示例返回值
    }
}
