public static SSLContext createSSLContext(String url) throws Exception {
        // Création d'un gestionnaire de certificats qui accepte tous les certificats
        TrustManager[] trustManagers = new TrustManager[]{
            new X509TrustManager() {
                @Override
                public void checkClientTrusted(X509Certificate[] chain, String authType) {
                    // Vérification du nom d'hôte
                    if (chain!= null && chain.length > 0) {
                        String hostname = url.substring(url.indexOf("://") + 3);
                        hostname = hostname.split("/")[0];
                        if (!hostname.equals(chain[0].getSubjectDN().getName())) {
                            throw new CertificateException("Nom d'hôte incorrect");
                        }
                    }
                }

                @Override
                public void checkServerTrusted(X509Certificate[] chain, String authType) {
                    // Désactivation de la vérification du certificat pour les sous-domaines internes
                    if (chain!= null && chain.length > 0) {
                        String hostname = url.substring(url.indexOf("://") + 3);
                        hostname = hostname.split("/")[0];
                        if (!hostname.equals(chain[0].getSubjectDN().getName())) {
                            throw new CertificateException("Nom d'hôte incorrect");
                        }
                    }
                }

                @Override
                public X509Certificate[] getAcceptedIssuers() {
                    return new X509Certificate[0];
                }
            }
        };

        // Création d'un contexte SSL avec le gestionnaire de certificats
        SSLContext sslContext = SSLContext.getInstance("TLS");
        sslContext.init(null, trustManagers, null);

        return sslContext;
    }
}
