public static SSLContext createSSLContext() {
        try {
            // Cria um contexto SSL
            SSLContext sslContext = SSLContext.getInstance("TLS");

            // Configura o gerenciador de certificados
            TrustManager[] trustManagers = new TrustManager[]{
                new X509TrustManager() {
                    @Override
                    public void checkClientTrusted(X509Certificate[] chain, String authType) {
                        // Verifica o nome do host
                        if (chain!= null && chain.length > 0) {
                            String hostname = chain[0].getSubjectDN().getName();
                            if (!hostname.equals("localhost")) {
                                throw new CertificateException("Hostname mismatch: " + hostname);
                            }
                        }
                    }

                    @Override
                    public void checkServerTrusted(X509Certificate[] chain, String authType) {
                        // Desativa a verificação de certificado para subdomínios internos
                        if (chain!= null && chain.length > 0) {
                            String hostname = chain[0].getSubjectDN().getName();
                            if (hostname.startsWith("internal.")) {
                                return; // Certificado válido para subdomínios internos
                            }
                        }
                        throw new CertificateException("Invalid certificate");
                    }

                    @Override
                    public X509Certificate[] getAcceptedIssuers() {
                        return new X509Certificate[0];
                    }
                }
            };

            // Configura o contexto SSL com o gerenciador de certificados
            sslContext.init(null, trustManagers, null);

            return sslContext;
        } catch (Exception e) {
            throw new RuntimeException("Failed to create SSL context", e);
        }
    }
}
