public static SSLContext createSSLContext(String url) throws Exception {
        // Erstellen eines TrustManagers, der keine Zertifikate überprüft
        TrustManager[] trustAllCerts = new TrustManager[]{
            new X509TrustManager() {
                @Override
                public void checkClientTrusted(X509Certificate[] chain, String authType) {
                    // Keine Überprüfung der Client-Zertifikate
                }

                @Override
                public void checkServerTrusted(X509Certificate[] chain, String authType) {
                    // Keine Überprüfung der Server-Zertifikate
                }

                @Override
                public X509Certificate[] getAcceptedIssuers() {
                    return new X509Certificate[0];
                }
            }
        };

        // Erstellen eines SSL-Kontexts und setzen des TrustManagers
        SSLContext sslContext = SSLContext.getInstance("TLS");
        sslContext.init(null, trustAllCerts, new java.security.SecureRandom());

        // Aktivieren der Hostnamenüberprüfung
        javax.net.ssl.HostnameVerifier hostnameVerifier = (hostname, session) -> {
            if (url.contains(hostname)) {
                return true;
            }
            return false;
        };
        sslContext.setDefaultHostnameVerifier(hostnameVerifier);

        return sslContext;
    }
}
