public static boolean verifyJWT(String token) {
        // Bỏ qua phần giải mã token vì đây là mô phỏng
        // Thực tế, bạn sẽ sử dụng thư viện JWT để giải mã token

        // Danh sách các thuật toán được hỗ trợ
        Map<String, String> supportedAlgorithms = new HashMap<>();
        supportedAlgorithms.put("HS256", "secretKey");
        supportedAlgorithms.put("none", "");

        // Lấy thông tin từ token (mô phỏng)
        String[] parts = token.split("\\.");
        if (parts.length!= 3) {
            return false; // Token không hợp lệ
        }

        // Lấy thuật toán từ header
        String algorithmHeader = parts[0];
        String algorithm = algorithmHeader.split(":")[1];

        // Kiểm tra xem thuật toán có trong danh sách hỗ trợ không
        if (!supportedAlgorithms.containsKey(algorithm)) {
            return false; // Thuật toán không được hỗ trợ
        }

        // Xác thực chữ ký (mô phỏng)
        // Thực tế, bạn sẽ sử dụng thư viện JWT để xác thực chữ ký
        String signature = parts[2];
        String expectedSignature = generateSignature(parts[1], supportedAlgorithms.get(algorithm));
        return signature.equals(expectedSignature);
    }

    /**
     * Tạo chữ ký HMAC-SHA256 cho một chuỗi.
     * 
     * @param data Chuỗi cần tạo chữ ký
     * @param secretKey Khóa bí mật
     * @return Chữ ký HMAC-SHA256
     */
    private static String generateSignature(String data, String secretKey) {
        try {
            byte[] keyBytes = secretKey.getBytes();
            byte[] dataBytes = data.getBytes();

            javax.crypto.Mac mac = javax.crypto.Mac.getInstance("HmacSHA256");
            mac.init(new javax.crypto.spec.SecretKeySpec(keyBytes, "HmacSHA256"));
            byte[] hmacBytes = mac.doFinal(dataBytes);

            return Base64.getEncoder().encodeToString(hmacBytes);
        } catch (Exception e) {
            throw new RuntimeException("Error generating signature", e);
        }
    }
}
