        String signature = parts[2];

        // Giải mã header
        Map<String, String> headerMap = decodeBase64(header);

        // Kiểm tra thuật toán chữ ký
        String algorithm = headerMap.get("alg");
        if (!algorithm.equals("HS256") &&!algorithm.equals("none")) {
            return false; // Thuật toán chữ ký không được hỗ trợ
        }

