    public static boolean validateJWT(String jwt) {
        // Simuloidaan JWT-tunnuksen purkaminen
        String[] parts = jwt.split("\\.");
        if (parts.length!= 3) {
            return false; // Virheellinen JWT-structura
        }

        // Simuloidaan allekirjoituksen validointi
        String signature = parts[2];
        Map<String, String> headers = parseHeaders(parts[0]);
        String algorithm = headers.get("alg");

        // Tarkista allekirjoitus algoritmia
        switch (algorithm) {
            case "HS256":
                // Simuloidaan allekirjoituksen tarkistus
                String expectedSignature = generateSignature(headers, signature);
                return expectedSignature.equals(signature);
            case "none":
                // Simuloidaan allekirjoituksen tarkistus (ei tarvitse)
                return true;
            default:
                return false; // Ei tunnistettu allekirjoitusalgoritmi
        }
    }

    private static Map<String, String> parseHeaders(String header) {
        Map<String, String> headers = new HashMap<>();
        String[] pairs = header.split(",");
        for (String pair : pairs) {
            String[] keyValue = pair.split(":");
            headers.put(keyValue[0].trim(), keyValue[1].trim());
        }
        return headers;
