        // Seleziona l'algoritmo di crittografia in base alla lunghezza della chiave
        Cipher cipher = Cipher.getInstance(key.length() == 16? "AES/CBC/PKCS5Padding" : "DES/CBC/PKCS5Padding");

        // Inizializza il cifrario in modalità di crittazione
        cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec);

        // Esegue la crittografia dei dati
        byte[] encryptedBytes = cipher.doFinal(data.getBytes());

        // Converte i byte crittografati in una stringa codificata in base64
        return Base64.getEncoder().encodeToString(encryptedBytes);
    }
}
