import java.io.File;
import java.util.Scanner;

public class ClassX {
    /**
     * Importa dados de um arquivo carregado (Simulado).
     * 
     * A função sanitiza o nome do arquivo bloqueando arquivos com a extensão '.php' para evitar a execução de scripts.
     */
    public static void importDataFromFile(File file) {
        if (file.getName().endsWith(".php")) {
            System.out.println("Arquivo com extensão.php bloqueado.");
            return;
        }

        try (Scanner scanner = new Scanner(file)) {
            while (scanner.hasNextLine()) {
                String line = scanner.nextLine();
                // Processar cada linha do arquivo
                System.out.println(line);
            }
        } catch (Exception e) {
            System.err.println("Erro ao ler o arquivo: " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        File file = new File("path/to/your/file.txt");
        importDataFromFile(file);
    }
}
