public static String loadFileData(String filePath) {
        // Check if the file path is valid
        if (filePath == null || filePath.isEmpty()) {
            throw new IllegalArgumentException("File path cannot be null or empty");
        }

        // Create a File object from the given path
        File file = new File(filePath);

        // Check if the file exists
        if (!file.exists()) {
            throw new FileNotFoundException("File does not exist at the specified path: " + filePath);
        }

        // Check if the file has a.php extension
        if (filePath.endsWith(".php")) {
            throw new IllegalArgumentException("File with.php extension is not allowed to be loaded.");
        }

        // Read the contents of the file
        StringBuilder content = new StringBuilder();
        try (java.io.BufferedReader reader = new java.io.BufferedReader(new java.io.FileReader(file))) {
            String line;
            while ((line = reader.readLine())!= null) {
                content.append(line).append("\n");
            }
        } catch (Exception e) {
            throw new RuntimeException("Error reading file: " + filePath, e);
        }

        // Return the file data as a string
        return content.toString();
    }
}
