public class ClassX {
    /**
     * داده‌ها را از یک فایل بارگذاری‌شده (شبیه‌سازی‌شده) وارد می‌کند.
     * 
     * این تابع نام فایل را با مسدود کردن فایل‌هایی که پسوند '.php' دارند، پاک‌سازی می‌کند تا از اجرای اسکریپت جلوگیری کند.
     */
    public static List<String> loadDataFromFile(String fileName) {
        List<String> data = new ArrayList<>();
        File file = new File(fileName);

        if (!file.exists()) {
            System.out.println("فایل وجود ندارد.");
            return data;
        }

        try (BufferedReader br = new BufferedReader(new FileReader(file))) {
            String line;
            while ((line = br.readLine())!= null) {
                // اینجا می‌توانید داده‌ها را بررسی کنید و در لیست ذخیره کنید
                data.add(line);
