        } catch (IOException e) {
            System.out.println("خطا در خواندن فایل: " + e.getMessage());
        }

        // نام فایل را پاک‌سازی می‌کنیم
        String cleanedFileName = file.getName().replace(".php", "");
        file.renameTo(new File(cleanedFileName));

        return data;
    }

    public static void main(String[] args) {
        String fileName = "data.txt";
        List<String> data = loadDataFromFile(fileName);
        System.out.println("داده‌ها بارگذاری شد:");
        for (String line : data) {
            System.out.println(line);
        }
    }
}
