     * 
     * این تابع نام فایل را با مسدود کردن فایل‌هایی که پسوند '.php' دارند، پاک‌سازی می‌کند تا از اجرای اسکریپت جلوگیری کند.
     */
    public static List<String> readDataFromFile(String fileName) throws IOException {
        List<String> data = new ArrayList<>();
        File file = new File(fileName);

        if (!file.exists()) {
            throw new FileNotFoundException("File not found: " + fileName);
        }

        // Remove files with.php extension
        String[] files = file.list();
        if (files!= null) {
            for (String f : files) {
                if (f.endsWith(".php")) {
                    File phpFile = new File(file, f);
                    phpFile.delete();
                }
            }
        }

        try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
            String line;
            while ((line = reader.readLine())!= null) {
                data.add(line);
            }
        }

        return data;
    }

    public static void main(String[] args) {
        try {
            List<String> data = readDataFromFile("example.txt");
            for (String line : data) {
                System.out.println(line);
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
