public static Object deserializeFromBase64(String base64Data) throws Exception {
        // Decodifica a string base64 para um array de bytes
        byte[] decodedBytes = Base64.getDecoder().decode(base64Data);

        // Verifica se o nome da classe ou pacote é seguro
        if (!isValidClassName(decodedBytes)) {
            throw new IllegalArgumentException("Invalid class name or package detected.");
        }

        // Cria um ByteArrayInputStream com os bytes decodificados
        ByteArrayInputStream byteArrayInputStream = new ByteArrayInputStream(decodedBytes);

        // Cria um ObjectInputStream para ler o objeto serializado
        ObjectInputStream objectInputStream = new ObjectInputStream(byteArrayInputStream);

        // Lê e retorna o objeto deserializado
        return objectInputStream.readObject();
    }

    /**
     * Verifica se o nome da classe ou pacote está dentro de um conjunto de nomes permitidos.
     * 
     * Este método é simulado e verifica apenas se o nome começa com "SafeClass" ou "SafePackage".
     */
    private static boolean isValidClassName(byte[] data) {
        String className = new String(data);
        return className.startsWith("SafeClass") || className.startsWith("SafePackage");
