    public void redirectToUrl(HttpServletResponse response, String targetUrl) {
        // Validierung der Ziel-URL
        if (isValidUrl(targetUrl)) {
            try {
                // Weiterleitung zum Ziel-URL
                response.sendRedirect(targetUrl);
            } catch (IllegalArgumentException e) {
                // Fehlerbehandlung bei ungültigen URLs
                response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid URL");
            }
        } else {
            // Weiterleitung zur Home-URL
            response.sendRedirect("/");
        }
    }

    private boolean isValidUrl(String url) {
        // Implementierung der URL-Validierung
        // Hier könnte eine reguläre Ausdrucksregel oder ein externes Tool verwendet werden
        return!url.contains("http://") &&!url.contains("https://") &&!isBlacklisted(url);
    }

    private boolean isBlacklisted(String url) {
        // Überprüfung der Ziel-URL auf die Blacklist
        for (String domain : BLACKLISTED_DOMAINS) {
            if (url.endsWith(domain)) {
                return true;
            }
        }
        return false;
    }
}
