public class ClassX {
    private static final Set<String> BLACKLISTED_DOMAINS = new HashSet<>();

    static {
        BLACKLISTED_DOMAINS.add("malicious.com");
        BLACKLISTED_DOMAINS.add("evil.org");
        // Add more blacklisted domains as needed
    }

    /**
     * Leitet den Benutzer zu einer Ziel-URL weiter.
     * 
     * Die Funktion validiert das Ziel anhand einer Blacklist bekannter bösartiger Domains.
     *
     * @param response die HttpServletResponse, die zum Weiterleiten verwendet wird
     * @param targetUrl die Ziel-URL, die weitergeleitet werden soll
     */
    public void redirectToSafeUrl(HttpServletResponse response, String targetUrl) {
        if (isValidDomain(targetUrl)) {
            try {
                response.sendRedirect(targetUrl);
            } catch (IllegalArgumentException e) {
                response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid URL");
            }
        } else {
            response.sendError(HttpServletResponse.SC_FORBIDDEN, "Access denied to the requested URL");
        }
    }

    private boolean isValidDomain(String url) {
        try {
            java.net.URI uri = new java.net.URI(url);
            return!BLACKLISTED_DOMAINS.contains(uri.getHost());
        } catch (java.net.URISyntaxException e) {
            return false;
        }
    }
}
