import javax.servlet.http.HttpServletResponse;
import java.util.HashSet;
import java.util.Set;

public class ClassX {
    private static final Set<String> BLACKLISTED_DOMAINS = new HashSet<>();

    static {
        BLACKLISTED_DOMAINS.add("maliciousdomain1.com");
        BLACKLISTED_DOMAINS.add("maliciousdomain2.com");
        // Agrega más dominios a la lista negra si es necesario
    }

    /**
     * Redirige al usuario a una URL de destino.
     * 
     * La función valida el destino contra una lista negra de dominios maliciosos conocidos.
     */
    public void redirectToSafeUrl(HttpServletResponse response, String destination) {
        if (destination == null || destination.isEmpty()) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid destination URL");
            return;
        }

        String domain = extractDomain(destination);

        if (BLACKLISTED_DOMAINS.contains(domain)) {
            response.sendError(HttpServletResponse.SC_FORBIDDEN, "Access to this URL is restricted");
            return;
        }

        try {
            response.sendRedirect(destination);
        } catch (IllegalArgumentException e) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid URL format");
        }
    }

    private String extractDomain(String url) {
        int index = url.indexOf("//");
        if (index!= -1) {
            url = url.substring(index + 2);
        }
        index = url.indexOf('/');
        if (index!= -1) {
            url = url.substring(0, index);
        }
        return url;
    }
}
