public class ClassX {
    private static final Set<String> BLACKLISTED_DOMAINS = new HashSet<>();
    static {
        BLACKLISTED_DOMAINS.add("maliciousdomain.com");
        BLACKLISTED_DOMAINS.add("anothermaliciousdomain.org");
    }

    /**
     * Redireciona o usuário para uma URL de destino.
     * 
     * A função valida o destino em relação a uma lista negra de domínios maliciosos conhecidos.
     */
    public void redirectToSafeUrl(HttpServletResponse response, String destination) {
        if (isBlacklisted(destination)) {
            response.sendRedirect("/error");
        } else {
            response.sendRedirect(destination);
        }
    }

    private boolean isBlacklisted(String url) {
        return BLACKLISTED_DOMAINS.contains(getDomainFromUrl(url));
    }

    private String getDomainFromUrl(String url) {
        int index = url.indexOf("//");
        if (index!= -1) {
            url = url.substring(index + 2);
        }
        index = url.indexOf('/');
        if (index!= -1) {
            url = url.substring(0, index);
        }
        return url;
    }
}
