                    response.append(line);
                }
                reader.close();

                // Der Schlüssel ist gültig, wenn die Antwort "valid" enthält
                return response.toString().equalsIgnoreCase("valid");
            } else {
                System.out.println("Fehler bei der API-Aufruf: " + responseCode);
                return false;
            }
        } catch (IOException e) {
            e.printStackTrace();
            return false;
        }
    }

